INSERT INTO transversal.error_knowledge (codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,lote_origen,estado,evidencia,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,source_ref)
VALUES
('SALY-F1-POLICY-DRIFT-20261128-001','TRANSPORT','Wire recalcula política LF congelada','RUN admitido con ventana 86400; configuración cambió a 60 y wire rechazó POLICY_DRIFT.','Comparación de política histórica con configuración viva.','FROZEN_POLICY_RECALCULATED','Para LF validar política congelada y enteros positivos, no recalcular; conservar ruta SALY.','W01/W01b/W01c/W01d reportados PASS local tras corrección; no desplegado.','HIGH',1,'SALY_CREATIVE_F1_20261128','ACTIVO','W01: configuración modificada durante RUN; wire vuelve a operar tras fix; negativos de política incompleta o fraccionaria bloquean.','DESIGN',ARRAY['CLAUDE_NATIVE','PROGRAMADOR'],'R2_NO_VE','PROCESS_DEPENDENT','SALY Fabrica Digital F1','SALY_F1_HANDOFF_20261128'),
('SALY-F1-PROJECT-CODE-20261128-001','REGRESSION','Código real SALY-001 distinto de business_code SALY','W02 candidato habría rechazado SALY real por comparar código de proyecto con business_code.','Fixture con código de proyecto inventado.','PROJECT_CODE_ASSUMPTION','Resolver proyecto real de la orden y mapear SALY-001 a SALY y LF a LF; probar ambos sentidos de mismatch.','W02a/b bloquean; W02c llega al guard SALY; O01 fixture representativo reporta mismo wire.','HIGH',1,'SALY_CREATIVE_F1_20261128','ACTIVO','Claude reportó descubrimiento por lectura de producción y corrección local; O01 parcial, no desplegado.','DESIGN',ARRAY['CLAUDE_NATIVE','PROGRAMADOR'],'R2_NO_VE','PROCESS_DEPENDENT','SALY Fabrica Digital F1','SALY_F1_HANDOFF_20261128'),
('SALY-F1-FIXTURE-COVERAGE-20261128-001','TESTING','Fixture reducido no equivale a regresión histórica completa','O01 con blueprint y datos reducidos demuestra paridad parcial, no cubre legacy sin blueprint, orden 22 histórica ni cierre SALY.','Cobertura del fixture no representa todo el universo.','FIXTURE_SCOPE_OVERCLAIM','Declarar denominador y diferencias; usar datos de catálogo reales representativos, sin datos personales; comparar base/candidata con triggers activos.','O01 L2A/L2C/L3B y wire iguales salvo ids generados; casos históricos, PG17 y matriz pendientes.','HIGH',1,'SALY_CREATIVE_F1_20261128','ACTIVO','Reporte Claude O01, backup5 referido no inspeccionado por GPT.','DESIGN',ARRAY['CLAUDE_NATIVE','PROGRAMADOR'],'R2_NO_VE','PROCESS_DEPENDENT','SALY Fabrica Digital F1','SALY_F1_HANDOFF_20261128'),
('SALY-F1-AUTH-EXEC-PROVENANCE-20261128-001','GOVERNANCE','Canal y actor de ejecución histórica no acreditados','ACL y worker_ref lógico no prueban el canal real ni independencia de autor/revisor.','Trazabilidad incompleta del actor/canal y confusión entre catálogo y autenticación.','DECLARED_ACTOR_NOT_ATTESTED','Conservar AUTH-EXEC01 NO_ACREDITADO_HISTORICAMENTE y AUTH-EXEC02 PASS_LOCAL_EMULADO; obtener evidencia del canal gobernado y de revisión independiente antes de afirmar autonomía.','AX1/AX1b denegados y AX2 local emulado; sin ejecución en producción.','HIGH',1,'SALY_CREATIVE_F1_20261128','ACTIVO','Reporte Claude: owner postgres NOSUPERUSER+BYPASSRLS; logs limitados; no evidencia histórica concluyente.','DESIGN',ARRAY['CLAUDE_NATIVE','PROGRAMADOR'],'R2_NO_VE','PROCESS_DEPENDENT','SALY Fabrica Digital F1','SALY_F1_HANDOFF_20261128'),
('SALY-F1-WIRE-ACL-PARITY-20261128-001','SECURITY','ACL local de render wire NULL frente a producción','Dueño reporta diferencia ACL entre sustrato local y producción; NULL no equivale a lista de permisos explícita.','Paridad de seguridad del fixture no acreditada.','ACL_FIXTURE_DRIFT','Comparar ACL efectiva, dueño, SECURITY DEFINER, RLS y permisos por rol contra catálogo vigente; probar negativos y no ampliar grants.','Pendiente evidencia específica de ACL local/prod y repetición con paridad; no declarar resuelto.','HIGH',1,'SALY_CREATIVE_F1_20261128','ACTIVO','Instrucción del dueño 28/11 03:05 Lima; detalle ACL local NULL vs prod reportado, no reproducido por GPT.','DESIGN',ARRAY['CLAUDE_NATIVE','PROGRAMADOR'],'R2_NO_VE','PROCESS_DEPENDENT','SALY Fabrica Digital F1','SALY_F1_HANDOFF_20261128')
ON CONFLICT (codigo) DO NOTHING;
INSERT INTO transversal.best_practices (categoria,titulo,practica,evidencia)
SELECT 'SALY_CREATIVE_F1',v.titulo,v.practica,v.evidencia FROM (VALUES
('[SALY-F1-BP-IMMUTABLE-SEAL-20261128] Sello de prompt inmutable y acceso mínimo','Separar registro y autorización; vincular prompt, literal, contexto y revisión; guard UPDATE/DELETE/TRUNCATE, RLS ENABLE FORCE, zero grants y locks compartidos con admisión.','SEAL01–08, S07–09, AX1/AX2 reportados locales; independencia y AUTH-EXEC01 pendientes.'),
('[SALY-F1-BP-REAL-FIXTURE-20261128] Probar contra datos reales representativos antes de aprobar','Leer catálogo real, mapear códigos y ACL; comparar base/candidata con triggers activos y reportar cobertura histórica, negativos y PG17; no copiar secretos ni datos personales.','W02 detectado por lectura de catálogo real SALY-001; O01 parcial con fixture reducido; no afirmar regresión completa.')
) v(titulo,practica,evidencia) WHERE NOT EXISTS (SELECT 1 FROM transversal.best_practices b WHERE b.titulo=v.titulo);
DO $qa$
BEGIN
 IF (SELECT count(*) FROM public.lf_error_knowledge WHERE codigo IN ('SALY-F1-POLICY-DRIFT-20261128-001','SALY-F1-PROJECT-CODE-20261128-001','SALY-F1-FIXTURE-COVERAGE-20261128-001','SALY-F1-AUTH-EXEC-PROVENANCE-20261128-001','SALY-F1-WIRE-ACL-PARITY-20261128-001'))<>5 THEN RAISE EXCEPTION 'SALY_F1_EKB_COUNT_INVALID'; END IF;
 IF (SELECT count(*) FROM public.lf_best_practices WHERE titulo IN ('[SALY-F1-BP-IMMUTABLE-SEAL-20261128] Sello de prompt inmutable y acceso mínimo','[SALY-F1-BP-REAL-FIXTURE-20261128] Probar contra datos reales representativos antes de aprobar'))<>2 THEN RAISE EXCEPTION 'SALY_F1_BP_COUNT_INVALID'; END IF;
END $qa$;
COMMIT;
